import { test } from '@playwright/test'
import { loginAsAdminOnce, waitForPageLoading, gotoHashPath, collectAppRoutes } from '../fixtures/auth-helpers.js'
import { pickSelectOption } from '../fixtures/form-helpers.js'

test('debug post-save state', async ({ page }) => {
  await loginAsAdminOnce(page)
  const routes = await collectAppRoutes(page)
  const listRoute = routes.find((r) => r.filePath === 'supervision/account/regulatorOrg/index' && !String(r.path).includes(':tableid'))
  await gotoHashPath(page, listRoute.path)
  await waitForPageLoading(page)
  await page.getByText('新增', { exact: true }).first().click()
  await waitForPageLoading(page)

  const ORG = `DBG机构${Date.now()}`
  await page.locator('input[placeholder="请输入机构名称"]').first().fill(ORG)
  await page.locator('input[placeholder="请输入统一社会信用代码"]').first().fill(`91320500DBG${String(Date.now()).slice(-6)}`)
  await page.locator('input[placeholder="请输入行政区划编码"]').first().fill('320505')
  await pickSelectOption(page, page.locator('.detail-container'), '机构类型', '', { dictType: 'REGULATOR_ORG_TYPE' })

  const respP = page.waitForResponse((r) => r.url().includes('/prefund/regulatorOrg/add'), { timeout: 30000 })
  await page.locator('[data-testid="detail-save-btn"]').first().click()
  const resp = await respP
  const body = await resp.json().catch(() => ({}))
  console.log('SAVE_RESP=', JSON.stringify({ status: resp.status(), code: body.code, data: body.data }))

  await page.waitForTimeout(4000)

  const state = await page.evaluate(() => {
    const app = document.querySelector('#app')?.__vue__
    const walk = (c, d = 0) => {
      if (!c || d > 8) return null
      if (c.$data && ('orgName' in (c.form || {}))) return c
      for (const ch of c.$children || []) { const f = walk(ch, d + 1); if (f) return f }
      return null
    }
    const comp = walk(app)
    const el = document.querySelector('.detail-container')
    return {
      hash: location.hash,
      formMode: comp?.formMode,
      formOrgName: comp?.form?.orgName,
      formOrgCode: comp?.form?.orgCode,
      contentInfoLen: comp?.contentInfo?.length,
      detailContainerText: (el?.innerText || '').replace(/\s+/g, ' ').slice(0, 300),
      hasDetailTemplate: !!document.querySelector('.detail-template, .detail-content'),
      formItemCount: document.querySelectorAll('.el-form-item').length
    }
  })
  console.log('POST_SAVE=', JSON.stringify(state, null, 2))
})

import { test } from '@playwright/test'
import { loginAsAdminOnce, waitForPageLoading, gotoHashPath, collectAppRoutes } from '../fixtures/auth-helpers.js'
import { pickSelectOption } from '../fixtures/form-helpers.js'

test('debug post-save state v2', async ({ page }) => {
  await loginAsAdminOnce(page)
  const routes = await collectAppRoutes(page)
  const listRoute = routes.find((r) => r.filePath === 'supervision/account/regulatorOrg/index' && !String(r.path).includes(':tableid'))
  await gotoHashPath(page, listRoute.path)
  await waitForPageLoading(page)
  await page.getByText('新增', { exact: true }).first().click()
  await waitForPageLoading(page)

  const ORG = `DBG2机构${Date.now()}`
  await page.locator('input[placeholder="请输入机构名称"]').first().fill(ORG)
  await page.locator('input[placeholder="请输入统一社会信用代码"]').first().fill(`91320500DB2${String(Date.now()).slice(-6)}`)
  await page.locator('input[placeholder="请输入行政区划编码"]').first().fill('320505')
  await pickSelectOption(page, page.locator('.detail-container'), '机构类型', '', { dictType: 'REGULATOR_ORG_TYPE' })

  // 先挂监听再点，避免时序竞态
  const respPromise = page.waitForResponse((r) => r.url().includes('/prefund/regulatorOrg/add'), { timeout: 20000 })
  await page.locator('[data-testid="detail-save-btn"]').first().click()
  const resp = await respPromise
  const body = await resp.json().catch(() => ({}))
  console.log('SAVE_RESP=', JSON.stringify({ status: resp.status(), code: body.code, data: body.data }))

  await page.waitForTimeout(5000)

  const state = await page.evaluate(() => {
    const app = document.querySelector('#app')?.__vue__
    const walk = (c, d = 0) => {
      if (!c || d > 10) return null
      const f = c.form || (c.$data && c.$data.form)
      if (f && typeof f === 'object' && 'orgName' in f) return c
      for (const ch of c.$children || []) { const r = walk(ch, d + 1); if (r) return r }
      return null
    }
    const comp = walk(app)
    return {
      hash: location.hash,
      formMode: comp?.formMode ?? null,
      formOrgName: comp?.form?.orgName ?? null,
      formOrgCode: comp?.form?.orgCode ?? null,
      contentInfoLen: comp?.contentInfo?.length ?? null,
      bodyText: document.body.innerText.replace(/\s+/g, ' ').slice(0, 400)
    }
  })
  console.log('POST_SAVE=' + JSON.stringify(state))
})

